import XCTest
@testable import LUACore
final class CoreTests:XCTestCase {
 func fixture()throws->URL{let root=FileManager.default.homeDirectoryForCurrentUser.appendingPathComponent("lua-test-"+UUID().uuidString);try FileManager.default.createDirectory(at:root,withIntermediateDirectories:true);addTeardownBlock{try? FileManager.default.removeItem(at:root)};return root}
 func testPathsAndSymlinks()throws{let root=try fixture();let file=root.appendingPathComponent("a.txt");try Data("safe".utf8).write(to:file);XCTAssertTrue(SafeFiles.contained(file,in:root));XCTAssertFalse(SafeFiles.contained(root,in:root));XCTAssertFalse(SafeFiles.contained(URL(fileURLWithPath:root.path+"-outside/a"),in:root));let link=root.appendingPathComponent("escape");try FileManager.default.createSymbolicLink(at:link,withDestinationURL:URL(fileURLWithPath:"/etc"));XCTAssertFalse(SafeFiles.contained(link.appendingPathComponent("hosts"),in:root));XCTAssertFalse(SafeFiles.allowedRoot(URL(fileURLWithPath:"/System")));XCTAssertFalse(SafeFiles.allowedRoot(FileManager.default.homeDirectoryForCurrentUser.appendingPathComponent("Library")))}
 func testScanDuplicateAndChangedFile()throws{let root=try fixture();for (name,text) in [("a","same"),("b","same"),("c","diff")]{try Data(text.utf8).write(to:root.appendingPathComponent(name))};let files=try SafeFiles.scan(root);XCTAssertEqual(files.count,3);let extra=try SafeFiles.duplicates(files);XCTAssertEqual(extra.count,1);XCTAssertEqual(extra[0].url.lastPathComponent,"b");try SafeFiles.validateForTrash(extra[0],root:root);try Data("changed".utf8).write(to:extra[0].url);XCTAssertThrowsError(try SafeFiles.validateForTrash(extra[0],root:root));XCTAssertThrowsError(try SafeFiles.scan(root,cancelled:{true}))}
 func testReplayUsesOnlyPastCompleteSegments(){let u=URL(fileURLWithPath:"/fixture");let s=(0..<8).map{ReplaySegment(url:u.appendingPathComponent("\($0)"),start:Double($0*3),end:Double(($0+1)*3))};let selected=ReplayPolicy.selected(s,now:18,seconds:7);XCTAssertEqual(selected.map{$0.end},[12,15,18]);XCTAssertTrue(selected.allSatisfy{$0.end<=18});XCTAssertFalse(selected.contains{$0.start>=18})}
 func testUpdateIntegrityContract()throws{let u=URL(string:"https://github.com/onekaer/lua-/releases/download/mac-v0.2.0/LUA-0.2.0-macOS-universal.zip")!;let f=UpdateFeed(version:"0.2.0",url:u,sha256:String(repeating:"a",count:64),bytes:3000);try f.validate();XCTAssertTrue(f.isNewer(than:"0.1.0"));XCTAssertFalse(f.isNewer(than:"0.3.0"));XCTAssertThrowsError(try UpdateFeed(version:"0.2.0",url:URL(string:"http://evil.example/app.zip")!,sha256:f.sha256,bytes:3000).validate());XCTAssertThrowsError(try UpdateFeed(version:"../../x",url:u,sha256:"wrong",bytes:0).validate())}
 func testStreamingHash()throws{let root=try fixture();let u=root.appendingPathComponent("hash");try Data("abc".utf8).write(to:u);XCTAssertEqual(try SafeFiles.hash(u),"ba7816bf8f01cfea414140de5dae2223b00361a396177a9cb410ff61f20015ad")}
 func testDuplicateCopyMustStillExist()throws{let root=try fixture();for name in ["a","b"]{try Data("same".utf8).write(to:root.appendingPathComponent(name))};let all=try SafeFiles.scan(root);let extra=try SafeFiles.duplicates(all);try SafeFiles.validateDuplicateBatch(extra,all:all,root:root);try FileManager.default.removeItem(at:root.appendingPathComponent("a"));XCTAssertThrowsError(try SafeFiles.validateDuplicateBatch(extra,all:all,root:root))}
}
